//! Borrowed primary named-argument positions for the original tracked scanner.
//! Requested positions only; no source/completion or semantic model is issued.
use crate::{reactive_original_source::{ReadSource,SelectedCallable},reactive_reads_native::Failure,captured_generator_budget::Budget,key_policy_control::{self as kc,Control},captured_allow_annotations::Operation};
use dm_analysis::policy_inputs::{PolicyInputs,PolicyFile,PolicyRole};
use dm_syntax::{Expr,ExprKind,ProjectedExprView,TypedVisitor,VisitDecision};
use std::{collections::{BTreeMap,BTreeSet},path::Path,io};
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;poll()?;b.require().map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))}
fn file<'a>(inputs:&'a PolicyInputs,path:&Path,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<Option<&'a PolicyFile>,Failure>{
 checked(budget,poll)?;if let Some(file)=inputs.file_exact(path){return Ok(Some(file))}
 let mut peak=path.as_os_str().len().checked_mul(8).and_then(|n|n.checked_add(512)).ok_or_else(||{budget.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())})?;budget.charge(peak).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;
 if let Some(file)=inputs.file(path){return Ok(Some(file))}
 let mut selected:Option<&'a PolicyFile>=None;
 for candidate in inputs.files(){checked(budget,poll)?;if !candidate.is_compiled()||candidate.role()!=PolicyRole::DmSource{continue}let wanted=path.as_os_str().len().checked_add(candidate.path().as_os_str().len()).and_then(|n|n.checked_mul(128)).and_then(|n|n.checked_add(4096)).ok_or_else(||{budget.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())})?;if wanted>peak{budget.charge(wanted-peak).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;peak=wanted;}if dm_preprocess::regions::relative_filesystem_path(candidate.path(),path).is_some_and(|relative|relative.as_os_str().is_empty()){if selected.is_some_and(|old|!std::ptr::eq(old,candidate)){return Err("tracked equivalent path names distinct actual compiled owners".into())}selected=Some(candidate);}}
 checked(budget,poll)?;Ok(selected)
}
pub(crate) struct Requests{rows:BTreeMap<usize,(String,BTreeSet<(usize,usize)>)>,discarded:Vec<(usize,dm_syntax::Span)>}
impl Requests{pub(crate) fn new()->Self{Self{rows:BTreeMap::new(),discarded:Vec::new()}}
 pub(crate) fn request(&mut self,inputs:&PolicyInputs,root:&Path,relative:&str,budget:&Budget,temporary:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{checked(budget,poll)?;let mut work=Operation{budget,poll};let mut local=Operation{budget:temporary,poll};kc::reserve(&mut local,||root.as_os_str().len().checked_add(relative.len())?.checked_mul(8)?.checked_add(512))?;let path=root.join(relative);let Some(actual)=file(inputs,&path,temporary,poll)?.filter(|file|file.is_compiled()&&file.role()==PolicyRole::DmSource)else{return Ok(())};let key=actual as *const PolicyFile as usize;if let Some((old,_))=self.rows.get(&key){if old!=relative{return Err("tracked requested aliases have distinct original report labels".into())}return Ok(())}kc::reserve(&mut work,||Some(2048))?;self.rows.insert(key,(kc::own(&mut work,relative)?,BTreeSet::new()));Ok(())}
 pub(crate) fn get(&self,inputs:&PolicyInputs,root:&Path,relative:&str,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<Option<&BTreeSet<(usize,usize)>>,Failure>{checked(budget,poll)?;budget.charge(root.as_os_str().len().checked_add(relative.len()).and_then(|n|n.checked_mul(8)).and_then(|n|n.checked_add(512)).ok_or_else(||{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"tracked original lookup overflow"))})?).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;let path=root.join(relative);let Some(actual)=file(inputs,&path,budget,poll)?.filter(|file|file.is_compiled()&&file.role()==PolicyRole::DmSource)else{return Ok(None)};let key=actual as *const PolicyFile as usize;let Some((label,rows))=self.rows.get(&key)else{return Err("compiled tracked source was not in requested position domain".into())};if label!=relative{return Err("tracked original report label differs".into())}Ok(Some(rows))}
 pub(crate) fn prepare(&mut self,source:&ReadSource<'_>,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{let inputs=source.inputs();let archive=inputs.archive();let tree=archive.tree();for(ordinal,occurrence)in archive.occurrences().iter().enumerate(){checked(budget,poll)?;if occurrence.source.macro_expansions.is_empty(){let Some(candidate)=file(inputs,&occurrence.source.path,budget,poll)?else{return Err("tracked body occurrence has no current original file".into())};if !self.rows.contains_key(&(candidate as *const PolicyFile as usize)){continue}}let identity=archive.callables().identity(ordinal).ok_or("tracked original callable identity absent")?;let owner=tree.symbols().text(identity.owner).ok_or("tracked original owner spelling absent")?;let name=tree.symbols().text(identity.name).ok_or("tracked original callable spelling absent")?;let point=archive.callable_header_source().reported_policy_line(occurrence.member)?;let Some(actual)=file(inputs,point.path.as_path(),budget,poll)?else{return Err("tracked original header has no current input owner".into())};let key=actual as *const PolicyFile as usize;let Some((_,rows))=self.rows.get_mut(&key)else{continue};if !matches!(source.callable_checked(owner,name)?,SelectedCallable::Source(ref call)if call.ordinal==ordinal){continue}let body=source.parse_body(ordinal).map_err(|failure|match failure{dm_tree::frontend::BodySyntaxFailure::Operational(actual)=>Failure::Operational(actual),dm_tree::frontend::BodySyntaxFailure::Syntax(error)=>Failure::Unsupported(error.message)})?;if !body.belongs_to(archive)||!body.statement_body().original_literal_syntax_complete(){return Err("tracked original body syntax is foreign or incomplete".into())}let mut walk=Positions{inputs,archive,expected:actual,budget,poll,rows,error:None,constructor_call:std::ptr::null(),discarded:&mut self.discarded,constructor_target:std::ptr::null()};dm_syntax::visit_statement_view(body.statement_body().view(),&mut walk);if let Some(actual)=walk.error{return Err(actual)}}checked(budget,poll)}
}
fn grouped<'a>(mut node:&'a Expr,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<&'a Expr,Failure>{while let ExprKind::Group(inner)=&node.kind{checked(budget,poll)?;node=inner;}Ok(node)}
fn has_named(args:&[Expr],budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<bool,Failure>{for arg in args{checked(budget,poll)?;if let ExprKind::Binary{op,lhs,..}=&arg.kind{if op=="="&&matches!(grouped(lhs,budget,poll)?.kind,ExprKind::Ident(_)){return Ok(true)}}}Ok(false)}
fn arguments<'a>(node:&'a Expr,constructor_call:bool,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<Option<&'a [Expr]>,Failure>{checked(budget,poll)?;Ok(match &node.kind{ExprKind::Call{..}if constructor_call=>None,ExprKind::Call{callee,args}=>match &callee.kind{ExprKind::Ident(name)if !matches!(name.as_str(),"pick"|"input"|"locate"|"call"|"call_ext"|"as"|"."|"..")=>Some(args),ExprKind::Member{..}|ExprKind::SafeMember{..}=>Some(args),ExprKind::StaticMember{..}=>None,ExprKind::Ident(_)=>None,ExprKind::Unary{op,..}if op=="::"=>None,ExprKind::Call{callee:primitive,..}if matches!(&primitive.kind,ExprKind::Ident(name)if name=="call"||name=="call_ext")=>None,ExprKind::TypePath(_)|ExprKind::ObjectInitializer{..}if constructor_call=>None,_=>{if has_named(args,budget,poll)?{return Err("tracked named argument call shape has not been issued".into())}None}},ExprKind::Unary{op,value}if op=="new"=>match &value.kind{ExprKind::Call{callee,args}if matches!(callee.kind,ExprKind::TypePath(_)|ExprKind::ObjectInitializer{..})=>Some(args),_=>None},_=>None})}
struct Positions<'a,'b>{inputs:&'a PolicyInputs,archive:&'a dm_tree::frontend::BodyArchive,expected:&'a PolicyFile,budget:&'b Budget,poll:&'b dyn Fn()->io::Result<()>,rows:&'b mut BTreeSet<(usize,usize)>,error:Option<Failure>,constructor_call:*const Expr,discarded:&'b mut Vec<(usize,dm_syntax::Span)>,constructor_target:*const Expr}
impl Positions<'_,'_>{fn leave(&mut self,node:&Expr){if self.discarded.last().is_some_and(|(owner,_)|*owner==node as *const Expr as usize){self.discarded.pop();}}fn enter(&mut self,node:&Expr,project:Option<ProjectedExprView<'_>>)->VisitDecision{if self.error.is_some(){return VisitDecision::Stop}let pending=(||{checked(self.budget,self.poll)?;if std::ptr::eq(self.constructor_target,node){self.constructor_target=std::ptr::null();return Ok::<bool,Failure>(false)}if self.discarded.last().is_some_and(|(_,range)|node.span.start>=range.start&&node.span.end<=range.end){return Ok::<bool,Failure>(false)}if let ExprKind::Call{callee,args}=&node.kind{if matches!(callee.kind,ExprKind::StaticMember{..}){if !args.is_empty(){if self.discarded.len()==self.discarded.capacity(){let wanted=self.discarded.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||{self.budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"tracked reference traversal capacity overflow"))})?;let bound=wanted.checked_mul(4).ok_or_else(||{self.budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"tracked reference traversal capacity overflow"))})?;self.budget.charge(bound.checked_mul(std::mem::size_of::<(usize,dm_syntax::Span)>()).and_then(|n|n.checked_add(128)).ok_or_else(||{self.budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"tracked reference traversal bytes overflow"))})?).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;self.discarded.try_reserve_exact(wanted-self.discarded.len()).map_err(|actual|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,actual)))?;if self.discarded.capacity()>bound{self.budget.deny();return Err(Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"tracked reference traversal actual capacity exceeds admission")))}}self.discarded.push((node as *const Expr as usize,dm_syntax::Span::new(callee.span.end,node.span.end)));}}}if let ExprKind::Unary{op,value}=&node.kind{if op=="new"&&!matches!(value.kind,ExprKind::Call{..}){self.constructor_target=&**value;}}let constructor_call=std::ptr::eq(self.constructor_call,node);if constructor_call{if let ExprKind::Call{callee,..}=&node.kind{self.constructor_target=&**callee;}}self.constructor_call=match &node.kind{ExprKind::Unary{op,value}if op=="new"&&matches!(&value.kind,ExprKind::Call{..})=>&**value,_=>std::ptr::null()};if let Some(args)=arguments(node,constructor_call,self.budget,self.poll)?{for arg in args{checked(self.budget,self.poll)?;let ExprKind::Binary{op,lhs,..}=&arg.kind else{continue};if op!="="{continue}let lhs=grouped(lhs,self.budget,self.poll)?;if !matches!(lhs.kind,ExprKind::Ident(_)){continue}let offset=match project{Some(project)=>project.current_span_of(lhs).ok_or("tracked argument escapes current primary projection")?.start,None=>lhs.span.start};let point=self.archive.callable_header_source().reported_source_point(offset)?;let Some(actual)=file(self.inputs,point.physical_path(),self.budget,self.poll)?else{return Err("tracked argument has no current original file".into())};if !std::ptr::eq(actual,self.expected){continue}let(_,line,column)=point.reported_coordinates();if !self.rows.contains(&(line,column)){self.budget.charge(2048).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;self.rows.insert((line,column));}}}Ok::<bool,Failure>(true)})();match pending{Ok(true)=>VisitDecision::Descend,Ok(false)=>VisitDecision::Skip,Err(actual)=>{self.error=Some(actual);VisitDecision::Stop}}}}
impl TypedVisitor for Positions<'_,'_>{fn leave_expression(&mut self,node:&Expr,_:&[dm_syntax::NodeStep]){self.leave(node)}fn leave_projected_expression(&mut self,node:ProjectedExprView<'_>,_:&[dm_syntax::NodeStep]){self.leave(node.original())}fn statement(&mut self,node:&dm_syntax::Statement,_:&[dm_syntax::NodeStep])->VisitDecision{if self.error.is_some(){return VisitDecision::Stop}if matches!(node.kind,dm_syntax::StatementKind::Unsupported){self.error=Some("tracked argument source contains unsupported primary syntax".into());return VisitDecision::Stop}match checked(self.budget,self.poll){Ok(())=>VisitDecision::Descend,Err(actual)=>{self.error=Some(actual);VisitDecision::Stop}}}fn expression(&mut self,node:&Expr,_:&[dm_syntax::NodeStep])->VisitDecision{self.enter(node,None)}fn projected_expression(&mut self,node:ProjectedExprView<'_>,_:&[dm_syntax::NodeStep])->VisitDecision{self.enter(node.original(),Some(node))}}
